INSERT INTO seller (user_id, name, description)
SELECT users.id, profiles.name, profiles.description
FROM (VALUES
    ('seed.digital-workshop@example.test', 'Цифровая мастерская', 'Магазин компьютерной периферии, аудиотехники и полезных аксессуаров для работы и дома.'),
    ('seed.northern-thread@example.test', 'Северная нить', 'Повседневная одежда и аксессуары из натуральных материалов для города и путешествий.'),
    ('seed.clay-and-wood@example.test', 'Глина и дерево', 'Мастерская керамики и деревянных предметов интерьера ручной работы.'),
    ('seed.beauty-room@example.test', 'Комната красоты', 'Магазин декоративной косметики и парфюмерии для повседневного ухода и особых случаев.'),
    ('seed.comfort-home@example.test', 'Уютный дом', 'Мебель и предметы интерьера для спальни, гостиной и рабочего пространства.'),
    ('seed.fresh-market@example.test', 'Свежая лавка', 'Продукты для домашней кухни и товары для домашних животных.')
) AS profiles(email, name, description)
JOIN "user" AS users ON users.email = profiles.email;

INSERT INTO product (category_id, seller_id, price, discount, name, description, available_count)
SELECT c.id, s.user_id, products.price, products.discount,
       products.name, products.description, products.available_count
FROM (VALUES
    ('Техника', 'seed.digital-workshop@example.test', 3490.00, 10, 'Беспроводная мышь Silent Click', 'Бесшумная мышь с регулируемой чувствительностью до 2400 DPI. Подключается по Bluetooth или через USB-приёмник, подходит для работы за ноутбуком.', 35),
    ('Техника', 'seed.digital-workshop@example.test', 7290.00, 5, 'Механическая клавиатура KeyCraft TKL', 'Компактная клавиатура без цифрового блока с тактильными переключателями, русской раскладкой и белой подсветкой. Съёмный кабель USB-C входит в комплект.', 18),
    ('Техника', 'seed.digital-workshop@example.test', 5490.00, 0, 'Наушники AirBeat Lite', 'Внутриканальные Bluetooth-наушники с микрофоном и сенсорным управлением. Работают до 6 часов без подзарядки и до 24 часов с зарядным футляром.', 24),
    ('Техника', 'seed.digital-workshop@example.test', 3190.00, 15, 'Внешний аккумулятор PowerGo 20000', 'Портативный аккумулятор ёмкостью 20000 мА·ч с разъёмами USB-A и USB-C. Поддерживает быструю зарядку мощностью до 20 Вт и показывает уровень заряда на дисплее.', 30),
    ('Техника', 'seed.digital-workshop@example.test', 4290.00, 0, 'USB-C хаб Connect 6 в 1', 'Алюминиевый адаптер с HDMI, двумя портами USB-A, USB-C Power Delivery и слотами для SD и microSD. Позволяет подключить монитор и периферию к ноутбуку одним кабелем.', 16),
    ('Техника', 'seed.digital-workshop@example.test', 8990.00, 10, 'Веб-камера ClearView Full HD', 'Камера для видеозвонков с разрешением 1920×1080 при 30 кадрах в секунду, автофокусом и встроенным микрофоном. Оснащена защитной шторкой и креплением на монитор.', 12),
    ('Одежда', 'seed.northern-thread@example.test', 2490.00, 0, 'Хлопковая футболка «Белое море»', 'Белая футболка прямого кроя из плотного хлопка 200 г/м² с небольшим принтом волны. Размер M, усиленный ворот и мягкие плоские швы.', 40),
    ('Одежда', 'seed.northern-thread@example.test', 5990.00, 10, 'Худи «Северный ветер»', 'Тёмно-синее худи свободного кроя из хлопкового футера с начёсом. Размер L, объёмный капюшон и карман-кенгуру для прохладной погоды.', 22),
    ('Одежда', 'seed.northern-thread@example.test', 1890.00, 5, 'Шапка из шерсти мериноса «Тайга»', 'Тёплая вязаная шапка оливкового цвета с широким отворотом. Состав: 80% шерсть мериноса и 20% полиамид, подходит на обхват головы 54–58 см.', 28),
    ('Одежда', 'seed.northern-thread@example.test', 1590.00, 0, 'Льняной шоппер «Городской маршрут»', 'Многоразовая сумка из плотной смеси льна и хлопка с внутренним карманом для ключей. Размер 38×42 см, длинные ручки позволяют носить её на плече.', 32),
    ('Уникальное', 'seed.clay-and-wood@example.test', 2190.00, 0, 'Керамическая кружка «Туман» 350 мл', 'Кружка ручной работы с удобной ручкой и матовой серо-голубой глазурью. Подходит для горячих напитков; оттенок и рисунок глазури могут немного отличаться у каждого изделия.', 10),
    ('Уникальное', 'seed.clay-and-wood@example.test', 3790.00, 5, 'Дубовая сервировочная доска «Лес»', 'Доска из массива дуба размером 35×20 см для подачи сыра, фруктов и закусок. Поверхность обработана пищевым минеральным маслом, предусмотрено отверстие для подвешивания.', 8),
    ('Уникальное', 'seed.clay-and-wood@example.test', 4590.00, 0, 'Керамическая ваза «Песчаный берег»', 'Настольная ваза высотой 22 см с фактурной поверхностью и песочной глазурью. Внутреннее покрытие удерживает воду, поэтому ваза подходит и для свежих цветов, и для сухоцветов.', 7),
    ('Уникальное', 'seed.clay-and-wood@example.test', 1290.00, 10, 'Набор подставок «Годовые кольца»', 'Четыре круглые подставки под чашки из берёзовой фанеры с гравировкой древесных колец. Диаметр 10 см, пробковая основа защищает стол от царапин.', 20)
) AS products(category, seller_email, price, discount, name, description, available_count)
JOIN category AS c ON c.category = products.category
JOIN "user" AS u ON u.email = products.seller_email
JOIN seller AS s ON s.user_id = u.id;

INSERT INTO product (id, category_id, seller_id, price, discount, name, description, available_count)
SELECT products.id, c.id, s.user_id, products.price, products.discount,
       products.name, products.description, products.available_count
FROM (VALUES
    (24, 'seed.beauty-room@example.test', 790.00, 10, 'Тушь для ресниц Essence Lash Princess', 'Чёрная тушь для выразительного макияжа глаз. Щёточка помогает распределить средство от корней до кончиков ресниц. Подходит для повседневного и вечернего макияжа. Компактный флакон удобно взять с собой.', 30),
    (25, 'seed.beauty-room@example.test', 1490.00, 5, 'Палетка теней с зеркалом', 'Палетка теней в тёплых оттенках для макияжа глаз. Внутреннее зеркало удобно использовать в дороге. Оттенки можно наносить по отдельности или сочетать между собой. Подходит для создания дневного и вечернего образа.', 18),
    (26, 'seed.beauty-room@example.test', 990.00, 0, 'Компактная пудра для лица', 'Компактная пудра помогает завершить макияж и придать коже матовый вид. Наносите её кистью или спонжем поверх тонального средства. Удобная упаковка поместится в косметичку. При необходимости макияж можно поправить в течение дня.', 22),
    (27, 'seed.beauty-room@example.test', 890.00, 10, 'Красная губная помада', 'Помада насыщенного красного оттенка для яркого акцента в макияже. Классический стик позволяет аккуратно нанести цвет на губы. Её можно использовать самостоятельно или вместе с карандашом. Упаковка легко помещается в сумку или карман.', 26),
    (28, 'seed.beauty-room@example.test', 490.00, 0, 'Красный лак для ногтей', 'Лак красного цвета для домашнего маникюра. Кисточка позволяет равномерно распределить покрытие по ногтевой пластине. Для более насыщенного оттенка можно нанести второй слой после высыхания первого. Завершите маникюр защитным покрытием по желанию.', 35),
    (29, 'seed.beauty-room@example.test', 4990.00, 5, 'Туалетная вода Calvin Klein CK One', 'Универсальный аромат Calvin Klein CK One для женщин и мужчин. В композиции сочетаются свежие цитрусовые и зелёные ноты. Спокойный характер аромата подходит для повседневного использования. Лаконичный флакон удобно разместить на туалетном столике.', 14),
    (30, 'seed.beauty-room@example.test', 16990.00, 0, 'Парфюмерная вода Chanel Coco Noir', 'Парфюмерная вода Chanel Coco Noir с выразительным восточным характером. В композиции сочетаются цветочные, цитрусовые и древесные оттенки. Аромат подойдёт для вечера и особого случая. Тёмный флакон сохраняет узнаваемые строгие линии марки.', 6),
    (31, 'seed.beauty-room@example.test', 14990.00, 5, 'Парфюмерная вода Dior J’adore', 'Цветочный аромат Dior J’adore с мягким и элегантным звучанием. В композиции раскрываются ноты жасмина и розы. Парфюмерная вода подойдёт для особого случая и повседневного образа. Изящный флакон станет украшением туалетного столика.', 8),
    (32, 'seed.beauty-room@example.test', 8990.00, 10, 'Парфюмерная вода Dolce Shine', 'Dolce Shine от Dolce & Gabbana — цветочно-фруктовый аромат с солнечным настроением. В композиции сочетаются фруктовые и белоцветочные ноты. Он подходит для тёплого времени года и дневных прогулок. Флакон с цветочной крышкой удобно хранить вдали от прямых солнечных лучей.', 9),
    (33, 'seed.beauty-room@example.test', 11990.00, 5, 'Парфюмерная вода Gucci Bloom', 'Gucci Bloom — цветочный аромат с нотами жасмина и туберозы. Его композиция напоминает о цветущем саде. Парфюмерная вода подходит для дневного и вечернего образа. Флакон в спокойном розовом оттенке дополнит коллекцию ароматов.', 10),
    (34, 'seed.comfort-home@example.test', 189000.00, 5, 'Двуспальная кровать Annibale Colombo', 'Двуспальная кровать Annibale Colombo для обустройства спальни. Высокое мягкое изголовье делает интерьер уютнее. Классический силуэт сочетается с лаконичным постельным бельём. Матрас и постельные принадлежности приобретаются отдельно.', 3),
    (35, 'seed.comfort-home@example.test', 249000.00, 5, 'Диван Annibale Colombo', 'Диван Annibale Colombo для гостиной или зоны отдыха. Мягкие сиденья и спинка создают удобное место для встреч и отдыха. Спокойная обивка сочетается с разными оттенками интерьера. За текстильной поверхностью рекомендуется ухаживать средствами для мебельной обивки.', 2),
    (36, 'seed.comfort-home@example.test', 16900.00, 0, 'Прикроватная тумба цвета африканской вишни', 'Прикроватная тумба в древесном оттенке африканской вишни. На столешнице удобно разместить лампу, книгу или стакан воды. Ящик поможет убрать небольшие личные вещи. Компактная форма подходит для пространства рядом с кроватью.', 8),
    (37, 'seed.comfort-home@example.test', 89000.00, 10, 'Кресло Knoll Saarinen Executive', 'Кресло Saarinen Executive от Knoll для рабочего кабинета или переговорной. Обтекаемая спинка и мягкое сиденье поддерживают комфорт во время работы. Дизайн Ээро Сааринена легко узнать по плавным линиям. Кресло подходит для обеденного стола и домашнего рабочего места.', 5),
    (38, 'seed.comfort-home@example.test', 54900.00, 0, 'Деревянная тумба с раковиной и зеркалом', 'Комплект для ванной комнаты с раковиной, деревянной тумбой и зеркалом. Пространство под раковиной удобно использовать для хранения принадлежностей. Зеркало дополняет зону умывания. Для установки и подключения сантехники рекомендуется обратиться к специалисту.', 4),
    (39, 'seed.fresh-market@example.test', 149.00, 0, 'Красные яблоки', 'Красные яблоки для перекуса и домашней выпечки. Их можно добавить в кашу, салат или фруктовую нарезку. Перед употреблением тщательно вымойте плоды. Храните яблоки в прохладном месте.', 60),
    (40, 'seed.fresh-market@example.test', 890.00, 5, 'Стейк из говядины', 'Говяжий стейк для приготовления на сковороде или гриле. Перед жаркой мясо можно приправить солью и любимыми специями. Готовьте продукт до безопасной степени прожарки. Храните охлаждённым и соблюдайте срок годности на упаковке.', 15),
    (41, 'seed.fresh-market@example.test', 690.00, 0, 'Сухой корм для кошек', 'Сухой корм для повседневного кормления взрослых кошек. Порцию следует подбирать с учётом веса и активности питомца. Рядом с миской всегда должна быть свежая питьевая вода. Состав и рекомендации по кормлению проверяйте на упаковке.', 24),
    (42, 'seed.fresh-market@example.test', 590.00, 5, 'Куриное мясо', 'Куриное мясо для приготовления домашних обедов и ужинов. Его можно запечь, потушить или использовать для супа. Перед подачей тщательно приготовьте мясо до полной готовности. Храните продукт охлаждённым и отдельно от готовой еды.', 20)
) AS products(id, seller_email, price, discount, name, description, available_count)
JOIN category AS c ON c.category = 'Уникальное'
JOIN "user" AS u ON u.email = products.seller_email
JOIN seller AS s ON s.user_id = u.id;

SELECT setval(pg_get_serial_sequence('product', 'id'),
              GREATEST((SELECT MAX(id) FROM product), (SELECT last_value FROM product_id_seq)), true);

INSERT INTO product_picture (product_id, picture_url)
SELECT id, '/media/product-pictures/' || id || '/thumbnail.webp'
FROM product
WHERE id BETWEEN 24 AND 42;
